events.inlineCode:
const idx = runtimeScene.getVariables().get("SoalIdx").getAsNumber();
const soal = runtimeScene.getGame().getVariables().get("Soal").getChild(idx);
const suara = soal.getChild("suara").getAsString();
if (suara) {
  gdjs.evtTools.sound.playSoundOnChannel(runtimeScene, suara, 2, false, 100, 1);
}
